// ── Secrets (from n8n Environment Variables — set in n8n Settings > Variables) ──
const supabaseUrl = $env.CAREER_VAULT_SUPABASE_URL;
const supabaseKey = $env.CAREER_VAULT_SUPABASE_SERVICE_KEY;
const openaiKey   = $env.CAREER_VAULT_OPENAI_KEY;
const webhookSecret = $env.CAREER_VAULT_WEBHOOK_SECRET;

if (!supabaseUrl || !supabaseKey || !openaiKey || !webhookSecret) {
  throw new Error('[Config] Variabili d\'ambiente n8n mancanti. Controlla Settings > Variables.');
}

// ── Autenticazione webhook ─────────────────────────────────────────────────
// L'app invia X-Internal-Secret nell'header per autenticare la richiesta.
const headers = $input.first().json.headers || {};
const incomingSecret = headers['x-internal-secret'] || headers['X-Internal-Secret'];
if (incomingSecret !== webhookSecret) {
  throw new Error('[Auth] Webhook secret non valido o mancante. Richiesta rifiutata.');
}

// ── Parsing body ───────────────────────────────────────────────────────────
const body = $input.first().json.body || $input.first().json;
const userId = body.userId || body.user_id || null;
if (!userId) throw new Error('[Validation] userId mancante nel payload.');

return [{ json: { supabaseUrl, supabaseKey, openaiKey, userId }, binary: $input.first().binary }];

const pdfText = $input.first().json.text || '';
if (!pdfText.trim()) throw new Error('Nessun testo estratto dal PDF. Assicurati che il PDF non sia solo immagini (scansionato).');
const openaiKey = $('⚙️ Config Import').first().json.openaiKey;
const schemaExample = JSON.stringify({ profile: { full_name: 'string|null', headline: 'string|null', phone: 'string|null', city: 'string|null', linkedin_url: 'string|null', portfolio_url: 'string|null', native_language: 'string|null' }, experiences: [{ type: 'work|education|certification|volunteer|project', title: 'string', organization: 'string|null', location: 'string|null', start_date: 'YYYY-MM-DD|null', end_date: 'YYYY-MM-DD|null', is_current: 'boolean', description: 'string|null', tags: 'string[]', skills: 'string[]' }], languages: [{ name: 'string', level: 'Madrelingua|C2|C1|B2|B1|A2|A1', proficiency: 'number' }] }, null, 2);
const systemPrompt = 'Sei un parser di CV professionale. Estrai le informazioni strutturate dal testo del CV e restituisci SOLO un oggetto JSON valido.

REGOLE FERREE — ZERO ALLUCINAZIONI:
1. NON inventare, supporre o dedurre informazioni non esplicitamente scritte nel CV.
2. Se un campo e poco chiaro, ambiguo o mancante: impostalo a null.
3. NON aggiungere esperienze, ruoli, competenze o date non nel testo.
4. Date in formato ISO YYYY-MM-DD. Solo anno noto: YYYY-01-01. Solo anno+mese: YYYY-MM-01. Sconosciuta: null.
5. is_current: true SOLO se il CV dice Presente, attuale, corrente o ongoing.
6. Lingue: livelli CEFR (A1, A2, B1, B2, C1, C2) o Madrelingua. Proficiency: A1=15, A2=30, B1=50, B2=65, C1=80, C2=95, Madrelingua=100.
7. Tipi esperienza — work: lavori/posizioni aziendali, education: studi/lauree/master, certification: certificazioni professionali (non linguistiche), volunteer: volontariato, project: progetti personali/accademici.
8. Certificazioni linguistiche (IELTS, TOEFL, DELF, ecc.) NON vanno in experiences, vanno in languages con il livello CEFR equivalente.
9. descriptions: copia il testo originale del CV, MAI inventato o abbellito. Se non c anulla: null.
10. tags: max 5 tag brevi e pertinenti (tecnologie, metodologie). skills: max 10 competenze brevi. Se vuoti: [].

Restituisci SOLO JSON valido. Nessun markdown, nessuna spiegazione, nessun testo extra.

Schema JSON atteso:
' + schemaExample;
return [{ json: { openaiKey, request: { model: 'gpt-4o', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: 'Testo del CV da analizzare:

' + pdfText }], response_format: { type: 'json_object' }, temperature: 0, max_tokens: 4096 } } }];

const raw = $input.first().json.choices?.[0]?.message?.content;
if (!raw) throw new Error('OpenAI non ha restituito contenuto');
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { throw new Error('JSON non valido da OpenAI: ' + raw.substring(0, 200)); }
const VALID_TYPES = ['work', 'education', 'certification', 'volunteer', 'project'];
const VALID_CEFR = ['Madrelingua', 'C2', 'C1', 'B2', 'B1', 'A2', 'A1'];
const CEFR_PROF = { Madrelingua: 100, C2: 95, C1: 80, B2: 65, B1: 50, A2: 30, A1: 15 };
const isValidDate = (d) => !d || /^\d{4}-\d{2}-\d{2}$/.test(d);
const profile = { full_name: parsed.profile?.full_name || null, headline: parsed.profile?.headline || null, phone: parsed.profile?.phone || null, city: parsed.profile?.city || null, linkedin_url: parsed.profile?.linkedin_url || null, portfolio_url: parsed.profile?.portfolio_url || null, native_language: parsed.profile?.native_language || null };
const experiences = (Array.isArray(parsed.experiences) ? parsed.experiences : []).filter(e => e && e.title && VALID_TYPES.includes(e.type)).map(e => ({ type: e.type, title: String(e.title).substring(0, 255), organization: e.organization ? String(e.organization).substring(0, 255) : null, location: e.location ? String(e.location).substring(0, 255) : null, start_date: isValidDate(e.start_date) ? (e.start_date || null) : null, end_date: isValidDate(e.end_date) ? (e.end_date || null) : null, is_current: Boolean(e.is_current), description: e.description ? String(e.description).substring(0, 2000) : null, tags: Array.isArray(e.tags) ? e.tags.slice(0, 5).map(t => String(t)) : [], skills: Array.isArray(e.skills) ? e.skills.slice(0, 10).map(s => String(s)) : [] }));
const languages = (Array.isArray(parsed.languages) ? parsed.languages : []).filter(l => l && l.name && VALID_CEFR.includes(l.level)).map(l => ({ name: String(l.name), level: l.level, proficiency: CEFR_PROF[l.level] ?? 50 }));
return [{ json: { profile, experiences, languages } }];

// ── Secrets (from n8n Environment Variables — set in n8n Settings > Variables) ──
const supabaseUrl   = $env.CAREER_VAULT_SUPABASE_URL;
const supabaseKey   = $env.CAREER_VAULT_SUPABASE_SERVICE_KEY;
const openaiKey     = $env.CAREER_VAULT_OPENAI_KEY;
const webhookSecret = $env.CAREER_VAULT_WEBHOOK_SECRET;

if (!supabaseUrl || !supabaseKey || !openaiKey || !webhookSecret) {
  throw new Error('[Config] Variabili d\'ambiente n8n mancanti. Controlla Settings > Variables.');
}

// ── Autenticazione webhook ─────────────────────────────────────────────────
const headers = $input.first().json.headers || {};
const incomingSecret = headers['x-internal-secret'] || headers['X-Internal-Secret'];
if (incomingSecret !== webhookSecret) {
  throw new Error('[Auth] Webhook secret non valido o mancante. Richiesta rifiutata.');
}

// ── Parsing body ───────────────────────────────────────────────────────────
const body = $input.first().json.body || $input.first().json;
const { userId, documentId, docType, jobDescription, templateId, requestedAt } = body;

if (!userId || !documentId) {
  throw new Error('[Validation] userId e documentId sono obbligatori.');
}

return [{ json: { supabaseUrl, supabaseKey, openaiKey, userId, documentId, docType, jobDescription, templateId, requestedAt } }];

// ── Verifica che il documento appartenga all'utente ──────────────────────
const docs = $input.first().json;
const docList = Array.isArray(docs) ? docs : [docs];

if (docList.length === 0 || !docList[0]?.id) {
  throw new Error('[Auth] Accesso negato: documentId non trovato o non appartiene all\'utente. userId=' + $('⚙️ Config Generate').first().json.userId);
}

// Passa i dati di config al nodo successivo
const cfg = $('⚙️ Config Generate').first().json;
return [{ json: cfg }];

// ── Legge dati dai nodi precedenti ───────────────────────────────────────
const cfg = $('⚙️ Config Generate').first().json;
const mergedItems = $('🔀 Merge Profile+Auth').all();
const profileArr = mergedItems[0]?.json;
const profile = Array.isArray(profileArr) ? profileArr[0] : profileArr;
const authUser = mergedItems[1]?.json;
const experiences = $('🗄 Fetch Experiences').all().map(item => item.json);

const { userId, docType, jobDescription, documentId, templateId, openaiKey, supabaseUrl, supabaseKey } = cfg;
const email = authUser?.email || null;

// ── Separa le esperienze per tipo ────────────────────────────────────────
const workExps    = experiences.filter(e => e.type === 'work');
const projectExps = experiences.filter(e => e.type === 'project');
const otherExps   = experiences.filter(e => e.type !== 'language_cert' && e.type !== 'work' && e.type !== 'project');

// ── Formatta le esperienze come testo leggibile per l'AI ─────────────────
function formatExp(e) {
  const range = e.is_current
    ? `${e.start_date || '?'} – Presente`
    : `${e.start_date || '?'} – ${e.end_date || '?'}`;
  const skills = [...(e.skills || []), ...(e.tags || [])].join(', ');
  return `[${(e.type || 'work').toUpperCase()}] ${e.title} @ ${e.organization || 'N/A'} (${range})
Descrizione: ${(e.description || '(nessuna)').slice(0, 500)}
Competenze: ${skills || 'N/A'}`;
}

const workText    = workExps.length    ? workExps.map(formatExp).join('

')    : '(Nessuna esperienza lavorativa disponibile)';
const projectText = projectExps.length ? projectExps.map(formatExp).join('

') : '(Nessun progetto disponibile)';
const otherText   = otherExps.length   ? otherExps.map(formatExp).join('

')   : '';

// ── Tone map ──────────────────────────────────────────────────────────────
const toneMap = {
  creative: `STILE CREATIVE – Tono persuasivo, narrativo e coinvolgente.
Il profile_summary deve raccontare il percorso professionale come una storia.`,
  minimal:  `STILE MINIMAL – Tono formale, diretto e denso di sostanza.
Il profile_summary deve essere preciso e privo di orpelli: solo fatti rilevanti.`,
  modern:   `STILE MODERN – Tono professionale ed equilibrato.
Il profile_summary deve unire precisione tecnica e leggibilità.`
};
const toneInstructions = toneMap[templateId] || toneMap.modern;

const systemPrompt = `Sei un esperto career coach italiano con 15 anni di esperienza.

TEMPLATE: ${templateId?.toUpperCase()}
${toneInstructions}

REGOLE ASSOLUTE
1. Usa SOLO i dati forniti. Vietato inventare.
2. Restituisci SOLO JSON valido. Zero markdown.
3. Esperienze work → array experiences. Progetti → array projects. Mai mescolare.

PROFILE SUMMARY: 5-7 frasi, prima persona, zero AI-speak (vietati: dinamico, proattivo, orientato ai risultati).

STRUTTURA JSON OBBLIGATORIA:
{
  "profile_summary": "str",
  "experiences": [{"title":"str","organization":"str","period":"str","description":"str","tags":["skill"]}],
  "projects":     [{"title":"str","organization":"str","period":"str","description":"str","tags":["tecnologia"]}],
  "education":    [{"title":"str","organization":"str","period":"str","description":"str o null","tags":[]}],
  "certifications":[{"title":"str","organization":"str","period":"str","description":"str o null","tags":[]}],
  "skills": ["skill1","skill2"]
}`;

const userPrompt = `JOB DESCRIPTION:
${jobDescription}

ESPERIENZE LAVORATIVE (type=work):
${workText}

PROGETTI (type=project):
${projectText}${otherText ? '

ALTRO (istruzione, certificazioni, ecc.):
' + otherText : ''}

Restituisci il JSON strutturato.`;

return [{ json: { userId, docType, jobDescription, documentId, templateId, openaiKey, supabaseUrl, supabaseKey, profile, email, systemPrompt, userPrompt } }];

const buildData = $('🧠 Build AI Prompt').first().json;
const aiRaw = $input.first().json.choices[0].message.content;

let aiData;
try {
  const cleaned = aiRaw.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  aiData = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI output non è JSON valido: ' + aiRaw.slice(0, 300));
}

const { profile, email, userId, documentId, supabaseUrl, supabaseKey } = buildData;

const fullName  = (profile?.full_name || '').trim();
const nameParts = fullName.split(' ').filter(Boolean);
const contact = {
  full_name:     fullName,
  first_name:    nameParts[0] || '',
  last_name:     nameParts.slice(1).join(' ') || '',
  initials:      nameParts.map(p => p[0] || '').join('').toUpperCase().slice(0, 2),
  headline:      profile?.headline      || null,
  city:          profile?.city          || null,
  phone:         profile?.phone         || null,
  email:         email                  || null,
  linkedin_url:  profile?.linkedin_url  || null,
  portfolio_url: profile?.portfolio_url || null,
  avatar_url:    profile?.avatar_url    || null
};

const CEFR_PROFICIENCY = { A1: 15, A2: 28, B1: 45, B2: 62, C1: 80, C2: 95, Madrelingua: 100 };
const languages = [];
if (profile?.native_language) {
  languages.push({ name: profile.native_language, level: 'Madrelingua', proficiency: 100 });
}

const allExperiences = $('🗄 Fetch Experiences').all().map(item => item.json);
const langCerts = allExperiences.filter(e => e.type === 'language_cert');
for (const cert of langCerts) {
  const cefrLevel = cert.tags?.[0] || null;
  const proficiency = cert.metadata?.proficiency || (cefrLevel ? (CEFR_PROFICIENCY[cefrLevel] || 60) : 60);
  languages.push({ name: cert.title || 'N/A', level: cefrLevel || cert.title || 'N/A', proficiency });
}

const mapItem = e => ({ title: e.title || '', organization: e.organization || '', period: e.period || '', description: e.description || '', tags: Array.isArray(e.tags) ? e.tags : [] });

const result = {
  contact,
  profile_summary: aiData.profile_summary || '',
  experiences:     (aiData.experiences    || []).map(mapItem),
  projects:        (aiData.projects       || []).map(mapItem),
  education:       (aiData.education      || []).map(mapItem),
  certifications:  (aiData.certifications || []).map(mapItem),
  skills:          aiData.skills          || [],
  languages
};

return [{ json: { result, userId, documentId, supabaseUrl, supabaseKey } }];
